/* --- Internal Machine Learning Mathematical Primitives --- */
/**
 * @file ml_internal.h
 * @brief Internal Mathematical & Distance Primitives for RCRE ML Subsystem
 */

#ifndef RCRE_ML_INTERNAL_H
#define RCRE_ML_INTERNAL_H

#include <stddef.h>
#include <stdint.h>
#include <math.h>

/**
 * @brief Canonical direct squared Euclidean L2 distance between two vectors.
 */
static inline float rcre_squared_l2_distance(const float* a, const float* b, size_t d) {
    float sum = 0.0f;
    for (size_t i = 0; i < d; ++i) {
        float diff = a[i] - b[i];
        sum += diff * diff;
    }
    return sum;
}

/**
 * @brief Numerically clamped logistic sigmoid activation.
 */
static inline float rcre_fast_sigmoidf(float z) {
    if (z > 16.0f) return 1.0f;
    if (z < -16.0f) return 0.0f;
    return 1.0f / (1.0f + expf(-z));
}

/**
 * @brief SplitMix64 pseudo-random number generator for reproducible sampling.
 */
static inline uint64_t rcre_splitmix64(uint64_t* state) {
    uint64_t z = (*state += 0x9e3779b97f4a7c15ULL);
    z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
    z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
    return z ^ (z >> 31);
}

/**
 * @brief Uniform floating-point random number generator in range [0.0, 1.0).
 */
static inline float rcre_rand_f32(uint64_t* state) {
    return (float)((rcre_splitmix64(state) >> 40) * (1.0 / 16777216.0));
}

#endif /* RCRE_ML_INTERNAL_H */

/* --- Internal Random Number Generation --- */
/**
 * @file rcre_rng.h
 * @brief RCRE Unified Random Number Generation (internal header)
 *
 * Single source of truth for PRNG state and distributions across RCRE
 * (tensor init, data ingestion, sampling). All code that needs randomness
 * MUST use these routines instead of local static copies.
 *
 * Algorithm: XorShift64* (Marsaglia, 2003) — 64-bit state, fast,
 * reproducible across platforms. Seed with a non-zero constant.
 */

#ifndef RCRE_RNG_H
#define RCRE_RNG_H

#include <stdint.h>
#include <math.h>

static inline uint64_t rcre_rng_next(uint64_t* state) {
    uint64_t x = *state;
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    *state = x;
    return x * 0x2545F4914F6CDD1DULL;
}

/** Uniform float in [lo, hi). */
static inline float rcre_rng_uniform_f32(uint64_t* state, float lo, float hi) {
    uint64_t r = rcre_rng_next(state);
    double u = (double)(r >> 11) * (1.0 / 9007199254740992.0); /* [0,1) */
    return lo + (float)(u * (hi - lo));
}

/** Standard-normal float (Box–Muller), scaled by `std` and shifted by `mean`. */
static inline float rcre_rng_gaussian_f32(uint64_t* state, float mean, float std) {
    float u1 = rcre_rng_uniform_f32(state, 1e-7f, 1.0f);
    float u2 = rcre_rng_uniform_f32(state, 0.0f, 1.0f);
    float z = sqrtf(-2.0f * logf(u1)) * cosf(2.0f * 3.14159265358979323846f * u2);
    return mean + z * std;
}

#endif /* RCRE_RNG_H */

